local config = {
  ui_story_32230401_1_dialog_content = "Cepat, ayo pergi!",
  ui_story_32230401_2_dialog_content = "Tunggu, apa? Ayo pergi? Ke mana?",
  ui_story_32230401_3_dialog_content = "Bukankah saya sudah memberi tahu Anda tentang \"hal kekacauan\" bahwa kita akan pergi ke \"tempat yang menarik\"?",
  ui_story_32230401_4_dialog_content = "\"Terminal,\" maksudmu.",
  ui_story_32230401_5_dialog_content = "Oh, aku mengerti sekarang. Kamu merasa terkurung terlalu lama dan ingin keluar, bukan?",
  ui_story_32230401_6_dialog_content = "Tidak sepenuhnya. Colossus Anda besar, menyenangkan, dan penuh dengan Aurorian yang keren.",
  ui_story_32230401_7_dialog_content = "Tapi aku ingin melihat lebih banyak lagi! Mainan keren, penemuan, spesialisasi Astra...",
  ui_story_32230401_8_dialog_content = "Aku mengerti! Tidak masalah kalau begitu. Aku akan membantumu.",
  ui_story_32230401_9_dialog_content = "Datang dan dapatkan rilis terbaru dari Bodyguard Wild Desert di sini dan temukan bagaimana cinta berbahaya itu berlangsung!",
  ui_story_32230401_10_dialog_content = "Ransum kalengan otentik dari Illumina. Kualitas terjamin. Jangan lewatkan kacang militer berkualitas ini!",
  ui_story_32230401_11_dialog_content = "Set orkestra lengkap dalam skala 1:30! Bermain melodi seperti band sungguhan!",
  ui_story_32230401_12_dialog_content = "Waow…",
  ui_story_32230401_13_dialog_content = "(Heh, Chen'ni bahkan tidak berkedip selama lima menit.)",
  ui_story_32230401_14_dialog_content = "Apakah saya membawa kamu ke tempat yang tepat atau bagaimana? Ketika kamu berbicara tentang koleksi barang-barang unik terbesar di sekitar...",
  ui_story_32230401_15_dialog_content = "Ini harusnya Umbraton!",
  ui_story_32230401_16_dialog_content = "Memang... Banyak hal yang benar-benar berbeda dari yang kamu lihat di Longzhou!",
  ui_story_32230401_17_dialog_content = "Kamu luar biasa, PlayerName!",
  ui_story_32230401_18_option_content = "Terima kasih atas pujianmu.",
  ui_story_32230401_19_dialog_content = "Aku tidak membangun kota ini. Aku hanya pemandu wisatamu.",
  ui_story_32230401_20_option_content = "Mengapa, tentu saja!",
  ui_story_32230401_21_dialog_content = "Kemanapun kamu ingin pergi, aku akan mengantarmu ke sana!",
  ui_story_32230401_22_dialog_content = "Hei, lihat ke sana! Figur kecil itu sedang memainkan alat musik mini...",
  ui_story_32230401_23_dialog_content = "Ah, model dari sebuah orkestra!",
  ui_story_32230401_24_dialog_content = "Sepertinya ini gadget dari Kerajaan Ye, tetapi bekerja berdasarkan prinsip yang berbeda...",
  ui_story_32230401_25_dialog_content = "(Mengetahui cara kerjanya hanya dengan sekilas? Seberapa cerdas kah naga-naga itu?)",
  ui_story_32230401_26_dialog_content = "Untuk apa kamu berdiri di sana, PlayerName? Bayar orang itu.",
  ui_story_32230401_27_dialog_content = "Hah?",
  ui_story_32230401_28_dialog_content = "Saya tidak punya Nightium. Bayar saja untuk saya sekarang; saya akan membayar Anda kembali nanti.",
  ui_story_32230401_29_dialog_content = "Oh, begitu... Baiklah, biarkan aku lihat berapa harganya...",
  ui_story_32230401_30_dialog_content = "... Kamu bisa menjualku menjadi budak dan itu pun masih tidak akan cukup untuk membayarnya!",
  ui_story_32230401_31_dialog_content = "Yakin? Kau satu-satunya Caelestite yang ada jadi aku tak mengharapkan kurang dari tebusan raja.",
  ui_story_32230401_32_dialog_content = "Bukan itu intinya, Nona Naga kesayangan!",
  ui_story_32230401_33_dialog_content = "Yah, aku tidak beruntung. Karena aku tidak bisa dengan tulus menjualmu...",
  ui_story_32230401_34_dialog_content = "Kurasa aku akan mencari tempat untuk menjual ini.",
  ui_story_32230401_35_dialog_content = "Emm... Apakah itu sepotong sisikmu?",
  ui_story_32230401_36_dialog_content = "Ya. Itu lepas dalam pertempuran brutal sebelumnya.",
  ui_story_32230401_37_dialog_content = "Tapi timbanganmu adalah harta yang akan dicari semua orang. Itu jauh lebih berharga daripada mainan!",
  ui_story_32230401_38_dialog_content = "(Hmm, sisik naga tidak ternilai harganya di Longzhou, tapi berapa harganya di Umbraton?)",
  ui_story_32230401_39_dialog_content = "Baiklah, mari kita coba peruntungan kita di toko barang antik terlebih dahulu.",
  ui_story_32230401_40_dialog_content = "Anu...",
  ui_story_32230401_41_dialog_content = "Anu…",
  ui_story_32230401_42_dialog_content = "Hmm…",
  ui_story_32230401_43_dialog_content = "Jadi, bagaimana menurutmu?",
  ui_story_32230401_44_dialog_content = "Apa? Beraninya kamu bertanya?",
  ui_story_32230401_45_dialog_content = "Ini tidak mungkin lebih palsu!",
  ui_story_32230401_46_dialog_content = "Tidak mungkin!",
  ui_story_32230401_47_dialog_content = "Anda bisa memanggil saya penipu sebanyak yang Anda mau, tetapi sisik naga ini bukan palsu. Ini jauh lebih asli daripada bangku batu Anda di sana!",
  ui_story_32230401_48_dialog_content = "Nah, sebenarnya bangku ini kosong di dalam, jadi...",
  ui_story_32230401_49_dialog_content = "...",
  ui_story_32230401_50_dialog_content = "Jadi berapa yang kamu pertimbangkan untuk sisik \"palsu\" naga ini?",
  ui_story_32230401_51_dialog_content = "Umm... Ini adalah pemalsuan yang terampil, tapi sayangnya sudah ternoda dan tidak bisa dihilangkan...",
  ui_story_32230401_52_dialog_content = "Itu darah naga. Hanya itu saja sudah layak untuk ditempatkan di Longzhou.",
  ui_story_32230401_53_dialog_content = "Mendapatkan semua dalam satu paket utuh adalah penawaran fantastis untuk Anda.",
  ui_story_32230401_54_dialog_content = "Longzhou ini, Longzhou itu... Itu adalah trik terbaru, bukan?",
  ui_story_32230401_55_dialog_content = "Tapi sayangnya, aku adalah berita buruk untukmu, Nona. Kamu tidak bisa membodohiku!",
  ui_story_32230401_56_dialog_content = "Penjaga toko dengan hati-hati membuka sebuah kotak untuk menunjukkan—",
  ui_story_32230401_57_dialog_content = "Apa-apaan ini? Mainan yang dibuang orang?",
  ui_story_32230401_58_dialog_content = "Mainan? Amatir! Apakah kalian bahkan mengenali salah satunya?",
  ui_story_32230401_59_dialog_content = "Saya baru saja membeli ini dengan uang yang baik dari Twin Pavilions Bay. Ini adalah relik suci yang ditinggalkan oleh Dragon Maiden yang telah meninggal!",
  ui_story_32230401_60_dialog_content = "Relik sakral...?!",
  ui_story_32230401_61_dialog_content = "Dari \"almarhum\" Gadis Naga?",
  ui_story_32230401_62_dialog_content = "Aku bahkan tidak menyadari bahwa aku sudah mati...",
  ui_story_32230401_63_dialog_content = "Lihat ini. Beginilah tampang skala Dragon Maiden yang asli!",
  ui_story_32230401_64_dialog_content = "Ketika kakek dari kaisar saat ini masih memegang tahta, dia pernah menyelamatkan Gadis Naga dari gurita raksasa dalam sebuah pelayaran...",
  ui_story_32230401_65_dialog_content = "Hah?",
  ui_story_32230401_66_dialog_content = "Sang Gadis Naga sangat berterima kasih sehingga dia memberinya sepotong sisiknya. Tetapi itu ditemukan di luar ketika istana itu dibobol...",
  ui_story_32230401_67_dialog_content = "Dan akhirnya, itu datang kepadaku.",
  ui_story_32230401_68_dialog_content = "Bagaimana? Saya bisa kurangi 1% dari harganya jika kamu benar-benar mau.",
  ui_story_32230401_69_dialog_content = "(Aku terlalu takut untuk melihat bagaimana reaksi Chen'ni terhadap semua ini...)",
  ui_story_32230401_70_dialog_content = "Um... Jelas sekali sisik ini berasal dari ikan ular, dan... Yah, tidak apa-apa. Mari kita tidak membahas itu sekarang.",
  ui_story_32230401_71_dialog_content = "Saya masih tertidur pulas di dasar laut ketika kaisar kakek itu berkuasa.",
  ui_story_32230401_72_dialog_content = "Saya lihat kamu menganggap dirimu sebagai Dragon Maiden. Bukankah kamu berkhayal, gadis kecil?",
  ui_story_32230401_73_dialog_content = "Tolong berhenti, aku mohon...",
  ui_story_32230401_74_dialog_content = "Anda menyuruh saya berhenti ketika Anda mencoba menipu saya, ahli Longzhou utama di sini?",
  ui_story_32230401_75_dialog_content = "Lihat ini? Ini adalah darah naga yang asli.",
  ui_story_32230401_76_dialog_content = "Bukankah ini hanya perunggu biasa?",
  ui_story_32230401_77_dialog_content = "Salah. Ini adalah baju besi yang dibuat oleh Suku Loom kuno dari Longzhou!",
  ui_story_32230401_78_dialog_content = "…!",
  ui_story_32230401_79_dialog_content = "Untuk menciptakan baju besi terkeras di dunia, mereka berdoa kepada Dragon Maiden.",
  ui_story_32230401_80_dialog_content = "Dan untuk menjawab doa mereka, Sang Gadis Naga meneteskan beberapa darahnya sendiri ke dalam tempa.",
  ui_story_32230401_81_dialog_content = "Setelah ribuan tahun, suku tersebut telah lama hilang, namun baju besi terakhir yang tak dapat ditembus di dunia ini...",
  ui_story_32230401_82_dialog_content = "Ini adalah satu-satunya bukti bahwa Suku Loom pernah ada!",
  ui_story_32230401_83_dialog_content = "Mengesankan, bukan? Tidak ada yang pernah melihat harta karun seperti ini sebelumnya!",
  ui_story_32230401_84_dialog_content = "Saya setuju. Ini juga baru pertama kalinya untukku.",
  ui_story_32230401_85_dialog_content = "Hehe... Hahahahah!",
  ui_story_32230401_86_dialog_content = "Kalian anak-anak ingusan! Beraninya kalian mengejek saya sambil mencoba menipu saya?",
  ui_story_32230401_87_dialog_content = "Kalahkan, kalahkan sekarang! Dan bawa barang palsu mu itu pergi!",
  ui_story_32230401_88_dialog_content = "Penjaga toko melihat noda darah saat dia meraih timbangan. Dia berhenti, mengerutkan kening, dan mengambilnya dengan kain sebelum membuangnya.",
  ui_story_32230401_89_dialog_content = "Pergi!",
  ui_story_32230401_90_dialog_content = "Ding dong!",
  ui_story_32230401_91_dialog_content = "Hahaha!",
  ui_story_32230401_92_dialog_content = "Ups, maaf, itu tidak lucu... Tapi kamu benar-benar memberikannya padanya!",
  ui_story_32230401_93_dialog_content = "Saya tidak bermaksud mempermalukannya, karena saya tahu betapa sedikit orang di sini yang tahu tentang naga-naga di Longzhou.",
  ui_story_32230401_94_dialog_content = "Sampai dia menyebutkan Suku Loom...",
  ui_story_32230401_95_dialog_content = "Nah, bagaimana kalau kita simpan saja timbangan berharga milikmu itu...",
  ui_story_32230401_96_dialog_content = "Tunggu, lap dengan yang orang itu membuang timbangan...",
  ui_story_32230401_97_dialog_content = "Apa yang salah? Dia mengambilnya secara acak dari mainan-mainan itu.",
  ui_story_32230401_98_dialog_content = "Ini hanya semacam kemasan, kira-kira.",
  ui_story_32230401_99_dialog_content = "Tidak berkerut saat Anda mengusapnya, kerajinan tangan yang unik, bahan yang kuat namun lembut...",
  ui_story_32230401_100_dialog_content = "Ini adalah peninggalan dari Suku Loom.",
  ui_story_32230401_101_dialog_content = "Suku kuno? Jadi si penjaga toko tidak berbohong?",
  ui_story_32230401_102_dialog_content = "Bagaimana jika menggunakan darahmu untuk membuat baju besi?",
  ui_story_32230401_103_dialog_content = "Itu bohong.",
  ui_story_32230401_104_dialog_content = "Aku melihat betapa asyiknya mereka dalam menenun dan merasa tertarik, cukup untuk melindungi mereka dari bencana untuk sementara waktu.",
  ui_story_32230401_105_dialog_content = "Selama hari-hari damai itu, mereka dengan cepat mengembangkan teknik tenun terbaik di dunia.",
  ui_story_32230401_106_dialog_content = "Begitulah manusia: cerdas, dan bertekad. Yang mereka butuhkan hanyalah kesempatan.",
  ui_story_32230401_107_dialog_content = "Aku tidak tahu bahwa itu benar-benar terjadi...",
  ui_story_32230401_108_dialog_content = "Seluruh suku hancur dalam kebakaran dan semua teknik mereka hilang.",
  ui_story_32230401_109_dialog_content = "Kain perca ini persis seperti \"harta karun yang belum pernah dilihat sebelumnya\" seperti yang dikatakan penjaga toko. Ini tak ternilai harganya.",
  ui_story_32230401_110_dialog_content = "Saya akan membawanya kembali ke Longzhou dan memperkenalkan kembali sejarah Loom ke dunia.",
  ui_story_32230401_111_dialog_content = "Tidak, sama sekali tidak!",
  ui_story_32230401_112_dialog_content = "Hei, kenapa kamu menguping di belakang pintu?",
  ui_story_32230401_113_dialog_content = "Kain lap itu milikku. Itu sangat berharga bagiku! Kembalikan sekarang juga padaku!",
  ui_story_32230401_114_dialog_content = "...",
  ui_story_32230401_115_dialog_content = "Jangan melampaui batas Anda, manusia fana.",
  ui_story_32230401_116_dialog_content = "Wow, naga... Itu naga! Argh...!",
  ui_story_32230401_117_dialog_content = "...",
  ui_story_32230401_118_dialog_content = "(Jadi begitulah rupa naga saat mereka marah! Belajar sesuatu yang baru hari ini.)",
  ui_story_32230401_119_dialog_content = "...",
  ui_story_32230401_120_dialog_content = "Baiklah, saatnya ke toko berikutnya!",
  ui_story_32230401_121_dialog_content = "Apa yang sedang kita lakukan?",
  ui_story_32230401_122_dialog_content = "Jual timbangan saya untuk modelnya, tentu saja!",
  ui_story_32230401_123_dialog_content = "Kamu masih mau melanjutkan itu?",
  ui_story_32230601_1_dialog_content = "Artemisia! Calamus! Saya juga menjual gardenia—",
  ui_story_32230601_2_dialog_content = "Nasi sorgum segar dijual! Tidak bisa membuat zongzi tanpa ini!",
  ui_story_32230601_3_dialog_content = "Saya tahu hari ini adalah Festival Warna Longzhou, tetapi saya tidak menyangka akan sehidup ini.",
  ui_story_32230601_4_dialog_content = "Nikmati pandanganmu, setiap orang! Pakaianku datang jauh-jauh dari barat—pemandangan yang jarang sekali terlihat!",
  ui_story_32230601_5_dialog_content = "Mereka bahkan menjual pakaian dari Astra di sini.",
  ui_story_32230601_6_dialog_content = "Aha! Seorang penikmat sejati, kusadari! Mari lihat, kawan!",
  ui_story_32230601_7_dialog_content = "Pakaian ini berasal dari Astra, tetapi mereka juga memiliki banyak pesona Longzhou. Ini pasti berasal dari Twin Pavilions Bay.",
  ui_story_32230601_8_dialog_content = "Menarik melihat mereka semua di sisi samudra ini.",
  ui_story_32230601_9_dialog_content = "Pakaian ini dipilih dengan hati-hati oleh Lin Guild. Setiap potongannya benar-benar unik.",
  ui_story_32230601_10_dialog_content = "Mereka membuat hadiah yang sempurna untuk para wanita di hidupmu.",
  ui_story_32230601_11_dialog_content = "Dan dengan Festival Warna yang sebentar lagi, setiap orang ingin terlihat terbaik dalam pakaian baru mereka!",
  ui_story_32230601_12_dialog_content = "Tidak bisa membiarkan gadis-gadis lain lebih bersinar dari dirimu sendiri, bukan?",
  ui_story_32230601_13_dialog_content = "Apakah itu juga tradisi festival lainnya?",
  ui_story_32230601_14_dialog_content = "(Sekarang aku berpikir tentang itu, Chen'ni selalu mengenakan pakaian yang sama. Aku bertanya-tanya...)",
  ui_story_32230601_15_dialog_content = "Saya bisa melihat bahwa kamu benar-benar memikirkannya. Sebagai tanda kejujuran saya, saya akan memberikan harga termurah di sekitar...",
  ui_story_32230601_16_dialog_content = "<color=#e8d9bb>Beberapa saat kemudian</color>",
  ui_story_32230601_17_dialog_content = "...",
  ui_story_32230601_18_dialog_content = "(Aku membelinya sebelum aku menyadarinya! Pedagang Kerajaan Ji benar-benar luar biasa...)",
  ui_story_32230601_19_dialog_content = "Yah, sepertinya aku sudah membayar untuk itu...",
  ui_story_32230601_20_dialog_content = "Dibayar untuk apa?",
  ui_story_32230601_21_dialog_content = "Ah! Chen'ni?",
  ui_story_32230601_22_dialog_content = "Um, aku dengar gadis-gadis suka memakai pakaian baru saat Festival Warna. Apakah kamu—",
  ui_story_32230601_23_dialog_content = "Yep, aku juga!",
  ui_story_32230601_24_dialog_content = "Hah?",
  ui_story_32230601_25_dialog_content = "Belum pernah kubilang sebelumnya? Pakaianku juga merupakan manifestasi dari kekuatanku.",
  ui_story_32230601_26_dialog_content = "Mereka terbuat dari sisik naga, yang berarti mereka kebal terhadap api, air, dan pengaruh roh jahat. Tentu saja, saya juga bisa mengubah penampilan mereka!",
  ui_story_32230601_27_dialog_content = "Jenis pakaian apa yang harus aku ganti, PlayerName? Mungkin salah satu gaun dari tanah airmu?",
  ui_story_32230601_28_dialog_content = "(Jadi tidak ada gunanya membeli ini setelah semua!)",
  ui_story_32230601_29_dialog_content = "Hahaha... Tentu, kedengarannya bagus.",
  ui_story_32230601_30_dialog_content = "?",
  ui_story_32230601_31_dialog_content = "Jadi... Apa yang baru saja kamu beli tadi?",
  ui_story_32230601_32_dialog_content = "(Aku tidak bisa melakukannya! Aku tidak bisa memberikannya kepadanya sekarang!)",
  ui_story_32230601_33_dialog_content = "T-Tidak ada apa-apa! Saya hanya terkejut menemukan begitu banyak produk dari Astra di sini, itu saja.",
  ui_story_32230601_34_dialog_content = "Lihat ke sana!",
  ui_story_32230601_35_dialog_content = "Makanan dan hiasan Barat! Jangan lewatkan kesempatanmu untuk membelinya!",
  ui_story_32230601_36_dialog_content = "Itu terlihat enak! Aku akan mengambil beberapa!",
  ui_story_32230601_37_dialog_content = "(Phew... Aku akan menyimpan ini untuk saat ini.)",
  ui_story_32230601_38_dialog_content = "Kemasan pada kudapan ini terlihat sangat rapat, dan saya tidak mengerti tulisan apa pun di atasnya. Mungkin lebih baik mencobanya terlebih dahulu!",
  ui_story_32230601_39_dialog_content = "Tunggu Chen'ni, itu—",
  ui_story_32230601_40_dialog_content = "*Nyam*",
  ui_story_32230601_41_dialog_content = "Sebuah biskuit militer super padat dari Federasi Illumina. Kamu seharusnya menambahkan air ke dalamnya...",
  ui_story_32230601_42_dialog_content = "*glek* Hmm?",
  ui_story_32230601_43_dialog_content = "B-Biskuit ini mengembang di mulutku!",
  ui_story_32230601_44_dialog_content = "Tetap tenang, Chen'ni! Cukup katakan saja!",
  ui_story_32230601_45_dialog_content = "Ini sangat kering! Biskuit ini menyerap semua kelembaban dari tubuhku!",
  ui_story_32230601_46_dialog_content = "Air... Aku butuh air!",
  ui_story_32230601_47_dialog_content = "Ada sungai di sana!",
  ui_story_32230601_48_dialog_content = "<color=#e8d9bb>Guyuran!</color>",
  ui_story_32230601_49_dialog_content = "... Chen'ni?",
  ui_story_32230601_50_dialog_content = "Ha! Camilan yang menarik!",
  ui_story_32230601_51_dialog_content = "Senang kau menyukainya, kira-kira... Di sini, ambil tangan saya sebelum kau merasa pusing karena berenang setelah makan.",
  ui_story_32230601_52_dialog_content = "Ah, semua pakaianku basah kuyup.",
  ui_story_32230601_53_dialog_content = "Hah? Tapi kamu baru saja bilang bajumu itu tahan terhadap—",
  ui_story_32230601_54_dialog_content = "Oh tidak, apa yang harus kulakukan sekarang? Ini benar-benar dilema.",
  ui_story_32230601_55_dialog_content = "Cukup gunakan kekuatanmu—",
  ui_story_32230601_56_dialog_content = "Aku bertanya-tanya di mana aku bisa menemukan setelan pakaian yang baru?",
  ui_story_32230601_57_dialog_content = "*memandang*",
  ui_story_32230601_58_dialog_content = "Yah, jika kamu akan menatap seperti itu... Silakan.",
  ui_story_32230601_59_dialog_content = "Terkadang saya berpikir kamu mungkin lebih baik dalam membaca pikiran daripada seorang Caelestite, Chen'ni.",
  ui_story_32230601_60_dialog_content = "Aku sama sekali tak paham maksudmu!",
  ui_story_32230601_61_dialog_content = "Bahkan seekor naga seperti diriku kadang lupa bagaimana cara mempertahankan sihirnya dari waktu ke waktu.",
  ui_story_32230601_62_dialog_content = "Ya tentu, apapun yang kamu katakan. Cepat naik ke sini, bisa?",
  ui_story_32230601_63_dialog_content = "Kebetulan, aku punya gaun yang pas untukmu.",
  ui_story_32230601_64_dialog_content = "Oh, PlayerName!",
  ui_story_32230601_65_dialog_content = "Gaun ini sangat lucu! Aku suka sekali!",
  ui_story_32230601_66_dialog_content = "Sudah lama sekali aku ingin mencoba pakaian Astra!",
  ui_story_32230601_67_dialog_content = "Senang kamu menyukainya.",
  ui_story_32230601_68_dialog_content = "Aku sudah lama ingin bertanya, tapi apa yang sedang kamu lakukan di sini?",
  ui_story_32230601_69_dialog_content = "Yah, begitulah…",
  ui_story_32230601_70_dialog_content = "Sebenarnya, saya sedang mencari sebuah keinginan.",
  ui_story_32230601_71_dialog_content = "Sebuah keinginan?",
  ui_story_32230601_72_dialog_content = "Setiap kali seseorang berdoa padaku dan memberikan persembahan, aku bisa mendengar keinginan terdalam di hati mereka!",
  ui_story_32230601_73_dialog_content = "Bagaimanapun juga, hidup di dunia fana adalah memiliki keinginan.",
  ui_story_32230601_74_dialog_content = "Beberapa orang merindukan kekayaan, otoritas, cinta, atau tempat yang bisa mereka sebut rumah mereka sendiri. Sementara yang lain hanya berharap segala sesuatu berjalan sesuai keinginan mereka.",
  ui_story_32230601_75_dialog_content = "Tapi harapan ini berbeda dari biasanya.",
  ui_story_32230601_76_dialog_content = "Yang aku tahu hanyalah ada seseorang yang memberikan persembahan kepadaku, tetapi entah kenapa, aku tidak bisa mendengar keinginan mereka dengan jelas.",
  ui_story_32230601_77_dialog_content = "Saya tidak punya pilihan selain muncul dan mencari tahu mengapa keinginan ini begitu sulit dipahami!",
  ui_story_32230601_78_dialog_content = "Aku mengerti, jadi kamu datang ke festival untuk mencari seseorang.",
  ui_story_32230601_79_dialog_content = "Biarkan saya membantu Anda. Mungkin kemampuan psikis saya bisa berguna di sini.",
  ui_story_32230601_80_dialog_content = "PlayerName…",
  ui_story_32230601_81_dialog_content = "Ada apa?",
  ui_story_32230601_82_dialog_content = "Tidak ada apa-apa. Bagaimana kalau kamu mencoba menggunakan kekuatanmu padaku?",
  ui_story_32230601_83_dialog_content = "Dengan begitu, aku bisa berbagi apa yang aku dengar denganmu.",
  ui_story_32230601_84_option_content = "Force Boost",
  ui_story_32230601_85_dialog_content = "Dragon Maiden, dengarlah permohonanku, aku berharap bisa naik jabatan tahun ini dan mendapatkan kekayaan.",
  ui_story_32230601_86_dialog_content = "Kekuatan Naga Suci yang Maha Penyayang! Tolong jaga saya selama perjalanan ini!",
  ui_story_32230601_87_dialog_content = "O Putri Naga yang perkasa, akankah saya menemukan pria impian saya?",
  ui_story_32230601_88_dialog_content = "Argh…",
  ui_story_32230601_89_dialog_content = "Kau baik-baik saja?",
  ui_story_32230601_90_dialog_content = "Ya, hanya sedikit pusing karena semua suara dalam pikiranmu barusan.",
  ui_story_32230601_91_dialog_content = "Inikah yang harus kamu dengar setiap detik setiap harinya?",
  ui_story_32230601_92_dialog_content = "Benar. Aku adalah dewi, ingat?",
  ui_story_32230601_93_dialog_content = "Wah, aku terus kalah dalam pertempuran rumput. Bisakah kamu tolong aku, Dragon Maiden?",
  ui_story_32230601_94_dialog_content = "O-Orang benar-benar berharap untuk hal-hal seperti ini? Hah? Kemana Chen'ni pergi?",
  ui_story_32230601_95_dialog_content = "Permainan ini tampak sangat menyenangkan! Bagaimana cara bermainnya?",
  ui_story_32230601_96_dialog_content = "Ini disebut pertempuran rumput, sayangku.",
  ui_story_32230601_97_dialog_content = "Pertama, kita harus menemukan dua batang rumput yang panjang. Lalu kita silangkan dan tarik, dan siapa pun yang mematahkan batang rumput orang lain menang.",
  ui_story_32230601_98_dialog_content = "Jika kamu menang tiga kali berturut-turut, kamu akan mendapatkan jepit rambut cantik ini.",
  ui_story_32230601_99_dialog_content = "(Ibuku terlalu sakit untuk keluar rumah. Aku ingin membuatnya senang dengan memenangkan ini untuknya, tapi aku terus kalah...)",
  ui_story_32230601_100_dialog_content = "Aku ingin bermain!",
  ui_story_32230601_101_dialog_content = "Sekarang? Tentu, tapi di mana kita seharusnya mencari rumput untuk permainan itu?",
  ui_story_32230601_102_dialog_content = "<color=#e8d9bb>Tanpa ragu sejenak, Chen'ni mencabut sehelai rambut dari ekornya.</color>",
  ui_story_32230601_103_dialog_content = "Ini, gunakan ini!",
  ui_story_32230601_104_dialog_content = "Hei!",
  ui_story_32230601_105_dialog_content = "(Tapi itu akan menjadi curang!)",
  ui_story_32230601_106_dialog_content = "(Jangan khawatir, aku akan menggunakan kekuatanku untuk memastikan tidak ada yang menyadarinya.)",
  ui_story_32230601_107_dialog_content = "(Oh, jadi sekarang kamu bisa menggunakan sihirmu?)",
  ui_story_32230601_108_dialog_content = "<color=#e8d9bb>Tiga pertandingan kemudian</color>",
  ui_story_32230601_109_dialog_content = "Saya menang!",
  ui_story_32230601_110_dialog_content = "Sulit untuk percaya! Aku telah bermain sepanjang hari, tetapi kamu adalah orang pertama yang mengalahkanku.",
  ui_story_32230601_111_dialog_content = "Ini, sekarang jepit rambut ini milikmu.",
  ui_story_32230601_112_dialog_content = "Lihat, PlayerName! Saya menang!",
  ui_story_32230601_113_dialog_content = "Wow, itu luar biasa.",
  ui_story_32230601_114_dialog_content = "(Meskipun kamu benar-benar curang...)",
  ui_story_32230601_115_dialog_content = "Pertempuran di rumput itu sangat menyenangkan, tapi sebenarnya aku tidak benar-benar membutuhkan jepit rambut ini.",
  ui_story_32230601_116_dialog_content = "Sepertinya aku harus membuangnya saja!",
  ui_story_32230601_117_dialog_content = "<color=#e8d9bb>Chen'ni melemparkan jepit rambut ke udara, di mana itu berputar dua kali sebelum dengan lembut mendarat di tangan gadis kecil.</color>",
  ui_story_32230601_118_dialog_content = "Ini Dragon Maiden! Dia benar-benar disini!",
  ui_story_32230601_119_dialog_content = "Berhenti berdiri diam, PlayerName! Masih banyak hal menyenangkan yang harus dilakukan!",
  ui_story_32230601_120_dialog_content = "Akan segera ke sana—hah?",
  ui_story_32230601_121_dialog_content = "Sangat manis... Sangat lapar.",
  ui_story_32230601_122_dialog_content = "Suara ini... Apakah ini juga dihitung sebagai permintaan?",
  ui_story_32230601_123_dialog_content = "Langsung saja ke kontes pembungkusan zongzi terbesar di Festival Warna! Daftarkan diri Anda bersama seorang teman sebelum putaran berikutnya dimulai!",
  ui_story_32230601_124_dialog_content = "PlayerName!",
  ui_story_32230601_125_dialog_content = "Biarkan saya menebak—kamu ingin mendaftar, bukan?",
  ui_story_32230601_126_dialog_content = "Ya!",
  ui_story_32230601_127_dialog_content = "Aturannya sederhana: tim mana pun yang membungkus zongzi terbanyak sebelum dupa ini habis terbakar memenangkan hadiah yang luar biasa!",
  ui_story_32230601_128_dialog_content = "Dan mulai!",
  ui_story_32230601_129_dialog_content = "Aku tahu mungkin agak aneh jika aku mengatakan ini sekarang.",
  ui_story_32230601_130_dialog_content = "Tapi Chen'ni...",
  ui_story_32230601_131_dialog_content = "Apakah kamu tahu cara membungkus \"zongzi\" ini?",
  ui_story_32230601_132_dialog_content = "Tidak ada sama sekali.",
  ui_story_32230601_133_dialog_content = "Aku juga tidak.",
  ui_story_32230601_134_dialog_content = "M-Mungkin kita harus melihat dulu bagaimana orang lain melakukannya?",
  ui_story_32230601_135_dialog_content = "...",
  ui_story_32230601_136_dialog_content = "Sangat mengejutkan ini mudah dilakukan. Saya rasa kami bisa menanganinya!",
  ui_story_32230601_137_dialog_content = "Kontes sekarang sudah setengah jalan! Mari terus semangati tim kita!",
  ui_story_32230601_138_dialog_content = "Semakin mudah saja membungkus ini. Saya rasa kita punya peluang nyata untuk menang sekarang! Sudah berapa banyak yang kita—",
  ui_story_32230601_139_dialog_content = "Uh, kemana perginya semua zongzi yang baru saja saya bungkus?",
  ui_story_32230601_140_dialog_content = "Hoik!",
  ui_story_32230601_141_dialog_content = "... Tidak! Muntahkan itu sekarang juga! Mereka masih mentah!",
  ui_story_32230601_142_dialog_content = "<color=#e8d9bb>Beberapa saat kemudian</color>",
  ui_story_32230601_143_dialog_content = "Waktu habis! Kontes sekarang telah berakhir!",
  ui_story_32230601_144_dialog_content = "Cepat sekali!",
  ui_story_32230601_145_dialog_content = "Pada akhirnya, kami hanya memiliki cukup waktu untuk membungkus satu zongzi saja.",
  ui_story_32230601_146_dialog_content = "Kami tidak memenangkan apa-apa, tapi pemilik kedai cukup baik untuk memasaknya untuk kami. Bau masakannya juga cukup enak.",
  ui_story_32230601_147_dialog_content = "Mencicit...",
  ui_story_32230601_148_dialog_content = "Hah? Apakah itu suaramu yang aku dengar tadi?",
  ui_story_32230601_149_dialog_content = "Nih, cobalah zongzi ini. Isinya adalah kurma merah, jadi rasanya manis dan enak.",
  ui_story_32230601_150_dialog_content = "Ciit!",
  ui_story_32230601_151_dialog_content = "<color=#e8d9bb>Fiendling kecil melompat dan mencium PlayerName di tangan sebelum berlari gembira dengan zongzinya.</color>",
  ui_story_32230601_152_dialog_content = "Hal kecil itu benar-benar menyukaimu, PlayerName.",
  ui_story_32230601_153_dialog_content = "... Itu lucu.",
  ui_story_32230601_154_dialog_content = "Meskipun kita tidak menang apa-apa, saya masih merasa sangat senang.",
  ui_story_32230601_155_dialog_content = "Apakah ini hal yang biasa kamu lakukan? Mendengarkan isi hati orang lain dan mengabulkan keinginan mereka?",
  ui_story_32230601_156_dialog_content = "Bagi seorang dewi sepertimu, kami tidak lebih dari sekedar pengunjung singkat dalam hidupmu.",
  ui_story_32230601_157_dialog_content = "Apa hubungannya dengan apa pun? Kamu bahagia sekarang, bukan?",
  ui_story_32230601_158_dialog_content = "Aku juga!",
  ui_story_32230601_159_dialog_content = "Dalam pandanganku, hidupmu tidak dapat dipungkiri singkat.",
  ui_story_32230601_160_dialog_content = "Namun, mungkin saja hidupku sama singkatnya dalam skema besar keberadaan.",
  ui_story_32230601_161_dialog_content = "Dalam arti itu, kita semua sama—Aurorian, fiendling, dan kita berdua juga.",
  ui_story_32230601_162_dialog_content = "Kita terbatas dalam eksistensi kita, ya.",
  ui_story_32230601_163_dialog_content = "Tapi di sini dan sekarang, kita sedang menikmati momen-momen singkat yang sama bersama, bukan begitu?",
  ui_story_32230601_164_dialog_content = "Sangat wajar jika kita ingin membuat momen-momen ini sebahagia mungkin.",
  ui_story_32230601_165_dialog_content = "Ayo pergi! Aku punya firasat kita masih punya banyak momen bahagia untuk dinikmati!",
  ui_story_32230601_166_dialog_content = "Tentu!",
  ui_story_32230601_167_dialog_content = "Yah, apa yang kamu katakan mungkin benar...",
  ui_story_32230601_168_dialog_content = "Tapi Chen'ni... Apakah kamu pikir kita bisa istirahat dulu?",
  ui_story_32230601_169_dialog_content = "Sudah lelah, PlayerName?",
  ui_story_32230601_170_dialog_content = "Yah, benar! Kami melakukan pertempuran rumput, membungkus zongzi, mengumpulkan ramuan, dan membantu pandai besi di tempat kerjanya...",
  ui_story_32230601_171_dialog_content = "Kami bahkan ikut serta dalam tiga balapan perahu naga sebagai pengganti menit terakhir!",
  ui_story_32230601_172_dialog_content = "Akan aneh jika aku tidak merasa lelah!",
  ui_story_32230601_173_dialog_content = "Baiklah, ini ada sepotong kue beras untuk membantumu memulihkan tenagamu.",
  ui_story_32230601_174_dialog_content = "Terima kasih... Tapi dari mana kamu mendapatkan ini?",
  ui_story_32230601_175_dialog_content = "Dari sebuah persembahan!",
  ui_story_32230601_176_dialog_content = "Lihat? Ada tempat suci yang didedikasikan untukku tepat di depan sana.",
  ui_story_32230601_177_dialog_content = "Bahkan di sini, ya? Semua orang pasti sangat menghormatimu, Chen'ni.",
  ui_story_32230601_178_dialog_content = "Hah? Apa itu...",
  ui_story_32230601_179_dialog_content = "Terima kasih banyak, Dragon Maiden. Ibu saya sangat menyukai hadiahnya.",
  ui_story_32230601_180_dialog_content = "Puji kamu, dewi ku, bisnisku berjalan sangat baik hari ini.",
  ui_story_32230601_181_dialog_content = "Ciit!",
  ui_story_32230601_182_dialog_content = "<color=#e8d9bb>Satu per satu, orang-orang meninggalkan berbagai jenis persembahan di tempat suci. Bahkan fiendling kecil itu meninggalkan bunga liar di sebelah tempat suci.</color>",
  ui_story_32230601_183_dialog_content = "Mengapa mereka semua meninggalkan utas ini juga?",
  ui_story_32230601_184_dialog_content = "Selama Festival Warna, sudah menjadi kebiasaan bagi orang-orang untuk saling mengirim benang berwarna-warni sebagai hadiah.",
  ui_story_32230601_185_dialog_content = "Setiap dari lima warna mewakili makna atau harapan yang berbeda.",
  ui_story_32230601_186_dialog_content = "Dengan mengepang lima warna menjadi gelang dan memakainya, orang bisa meningkatkan keberuntungan mereka dan menghindari bencana.",
  ui_story_32230601_187_dialog_content = "Menawarkan benang-benang ini kepada saya juga merupakan cara mereka untuk mengungkapkan rasa terima kasih.",
  ui_story_32230601_188_dialog_content = "Sayangnya, saya hanya melihat empat warna di sini, bukan lima.",
  ui_story_32230601_189_dialog_content = "Tapi tidak ada yang benar-benar sempurna, 'kan?",
  ui_story_32230601_190_dialog_content = "Sama seperti hari ini, kita banyak bersenang-senang meskipun tidak menemukan orang yang membuat permintaan aneh itu.",
  ui_story_32230601_191_dialog_content = "Tidak, aku pasti sudah menemukannya sejak lama.",
  ui_story_32230601_192_dialog_content = "Benarkah? Kapan itu terjadi?",
  ui_story_32230601_193_dialog_content = "Tepat ketika saya mendapatkan gaun ini, sebenarnya.",
  ui_story_32230601_194_dialog_content = "Suara itu adalah milikmu, PlayerName.",
  ui_story_32230601_195_dialog_content = "?",
  ui_story_32230601_196_dialog_content = "Penawaranmu sangat menyenangkan hatiku. Ucapkan keinginanmu, dan aku akan mengabulkannya untukmu.",
  ui_story_32230601_197_option_content = "Nah, saya memang punya satu keinginan.",
  ui_story_32230601_198_dialog_content = "Lalu sebutkan ambisi atau objek yang Anda inginkan, dan saya akan menjadikannya milik Anda.",
  ui_story_32230601_199_dialog_content = "Aku tidak tertarik dengan semua itu.",
  ui_story_32230601_200_option_content = "Saya tidak punya keinginan.",
  ui_story_32230601_201_dialog_content = "Kenapa?",
  ui_story_32230601_202_dialog_content = "Karena gaun itu bukanlah sebuah persembahan, atau cara saya meminta sebuah permohonan.",
  ui_story_32230601_203_dialog_content = "Aku hanya ingin memberimu hadiah, Chen'ni.",
  ui_story_32230601_204_dialog_content = "Kalau aku harus menempelkan sebuah harapan pada itu...",
  ui_story_32230601_205_dialog_content = "Maka itu pasti demi kebaikanmu.",
  ui_story_32230601_206_dialog_content = "Kekuasaan Naga Mulia yang Penuh Kebaikan, dengarlah permohonanku—",
  ui_story_32230601_207_dialog_content = "Harapan saya adalah kamu selalu sebahagia ini!",
  ui_story_32230601_208_dialog_content = "Setelah bertahun-tahun, saya telah kehilangan hitungan berapa banyak orang yang membuat permintaan untuk saya penuhi. Mengapa kamu membuat permintaan untuk kepentinganku?",
  ui_story_32230601_209_dialog_content = "Bahkan jika kamu membuat permintaan yang cukup egois, saya tidak keberatan untuk mengabulkannya.",
  ui_story_32230601_210_dialog_content = "Apakah kamu yakin tidak akan menyesal telah menyia-nyiakan kesempatan langka seperti ini?",
  ui_story_32230601_211_dialog_content = "Tentu saja aku tidak akan.",
  ui_story_32230601_212_dialog_content = "Hadiah ditujukan untuk membuat orang bahagia, dan itu saja.",
  ui_story_32230601_213_dialog_content = "Karena kamu menyebutnya hadiah...",
  ui_story_32230601_214_dialog_content = "Sudah sepantasnya aku memberikan sesuatu untukmu sebagai balasan.",
  ui_story_32230601_215_dialog_content = "Oh, jangan khawatir tentang itu. Saya hanya kebetulan membelinya karena hawa nafsu—",
  ui_story_32230601_216_dialog_content = "Ulurkan tanganmu, PlayerName.",
  ui_story_32230601_217_dialog_content = "<color=#e8d9bb>Tiba-tiba, angin di sekitar mereka berhenti sama sekali.</color>",
  ui_story_32230601_218_dialog_content = "<color=#e8d9bb>Dengan sebuah gerakan, Chen'ni memanggil benang hijau dari kuilnya, yang melayang dan melingkari pergelangan tangan PlayerName.</color>",
  ui_story_32230601_219_dialog_content = "Seutas benang hijau untuk mewakili hutan, timur, dan musim semi yang memberi kehidupan.",
  ui_story_32230601_220_dialog_content = "May semoga angin musim semi membawamu kesehatan dan kebahagiaan.",
  ui_story_32230601_221_dialog_content = "<color=#e8d9bb>Sebuah benang merah melayang dan merajut dirinya mengelilingi benang hijau.</color>",
  ui_story_32230601_222_dialog_content = "Seutas merah mewakili api, selatan, dan musim panas yang berkembang.",
  ui_story_32230601_223_dialog_content = "May panas musim panas memberimu kekuatan dan keberanian.",
  ui_story_32230601_224_dialog_content = "<color=#e8d9bb>Seutas benang putih meluncur dan membelit dirinya dengan dua lainnya.</color>",
  ui_story_32230601_225_dialog_content = "Seutas putih untuk mewakili guntur, barat, dan musim gugur yang berlimpah.",
  ui_story_32230601_226_dialog_content = "May panen musim gugur membawa kesuksesan dalam semua usaha Anda.",
  ui_story_32230601_227_dialog_content = "<color=#e8d9bb>Seutas benang hitam melayang dan dengan lincah menambahkan dirinya ke gelang.</color>",
  ui_story_32230601_228_dialog_content = "Seutas hitam untuk mewakili air, utara, dan musim dingin yang tak terhindarkan.",
  ui_story_32230601_229_dialog_content = "May badai musim dingin membawamu kehidupan baru dan pencerahan.",
  ui_story_32230601_230_dialog_content = "<color=#e8d9bb>Dengan itu, semua benang di kuil telah habis digunakan.</color>",
  ui_story_32230601_231_dialog_content = "Meski hanya dengan empat warna, gelang ini benar-benar indah. Aku suka sekali!",
  ui_story_32230601_232_dialog_content = "Itu bagus dan semua, tapi apa jenis teman yang akan saya jadi jika saya memberimu hadiah yang belum selesai? Menonton ini!",
  ui_story_32230601_233_dialog_content = "<color=#e8d9bb>Chen'ni mengangkat tangannya dan menyatukan jarinya. Energi ilahinya meluap dan membentuk benang emas di udara.</color>",
  ui_story_32230601_234_dialog_content = "Seutas benang emas untuk mewakili pusat, naga, dan...",
  ui_story_32230601_235_dialog_content = "Aku!",
  ui_story_32230601_236_dialog_content = "Hah?",
  ui_story_32230601_237_dialog_content = "<color=#e8d9bb>Jika kamu mengangkat wajahmu sekarang, kamu akan melihat matanya berkilau dengan kegembiraan.</color>",
  ui_story_32230601_238_dialog_content = "Saya hanya akan mengatakan ini sekali, PlayerName—",
  ui_story_32230601_239_dialog_content = "Tolong jaga kesehatan dan hidup lebih lama.",
  ui_story_32230601_240_dialog_content = "Dengan cara ini, kita bisa berbagi lebih banyak momen bahagia bersama-sama.",
  ui_story_32230601_241_dialog_content = "Meski mungkin itu tidak seberapa dibandingkan dengan umurmu...",
  ui_story_32230601_242_dialog_content = "Aku akan melakukan yang terbaik untuk terus maju.",
  ui_story_32230601_243_dialog_content = "Ini seharusnya tidak terlalu sulit, karena aku memiliki kamu yang mengawasiku.",
  ui_story_32230601_244_dialog_content = "<color=#e8d9bb>Chen'ni dengan hati-hati mengikat kedua ujung gelang tersebut, benang emas berkilauan terang di antara empat warna lainnya.</color>",
  ui_story_32230601_245_dialog_content = "May seluruh keindahan dunia menari atas namamu, dan May semoga kepemimpinan bijakmu berkembang selama seribu tahun.",
  ui_story_32230601_246_dialog_content = "May semua hal di dunia ini mendukung terwujudnya keinginanmu...",
  ui_story_32230601_247_dialog_content = "Untuk selama-lamanya."
}
return config
